[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>ScreenVault — UI & UX Design Inspiration</title>
  <style>
    /* ── Reset & Base ── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --black: #141414;
      --white: #ffffff;
      --gray-50: #f9f9f9;
      --gray-100: #f5f5f5;
      --gray-200: #e8e8e8;
      --gray-400: #a0a0a0;
      --gray-600: #6b6b6b;
      --accent: #5b4bff;
      --accent-light: #ede9ff;
      --accent-hover: #4a3ae8;
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --shadow-sm: 0 1px 3px rgba(0,0,0,.07), 0 1px 2px rgba(0,0,0,.05);
      --shadow-md: 0 4px 16px rgba(0,0,0,.09), 0 1px 4px rgba(0,0,0,.06);
      --shadow-lg: 0 12px 40px rgba(0,0,0,.12), 0 2px 8px rgba(0,0,0,.06);
      --font: 'Inter', system-ui, -apple-system, sans-serif;
    }
    html { scroll-behavior: smooth; }
    body {
      font-family: var(--font);
      background: var(--white);
      color: var(--black);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }
    a { color: inherit; text-decoration: none; }
    img { display: block; max-width: 100%; }
    button { font-family: inherit; cursor: pointer; border: none; }

    /* ── Typography ── */
    .text-xs  { font-size: .75rem;  line-height: 1.5; }
    .text-sm  { font-size: .875rem; line-height: 1.6; }
    .text-base{ font-size: 1rem;    line-height: 1.6; }
    .text-lg  { font-size: 1.125rem;line-height: 1.5; }
    .text-xl  { font-size: 1.25rem; line-height: 1.4; }
    .text-2xl { font-size: 1.5rem;  line-height: 1.3; }
    .text-3xl { font-size: 1.875rem;line-height: 1.2; }
    .text-4xl { font-size: 2.5rem;  line-height: 1.15; }
    .text-5xl { font-size: 3.25rem; line-height: 1.1; }
    .text-6xl { font-size: 4rem;    line-height: 1.05; }
    .font-medium { font-weight: 500; }
    .font-semibold { font-weight: 600; }
    .font-bold { font-weight: 700; }
    .text-gray { color: var(--gray-600); }
    .text-center { text-align: center; }

    /* ── Layout ── */
    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }
    .section { padding: 96px 0; }
    .section-sm { padding: 64px 0; }

    /* ── Buttons ── */
    .btn {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 12px 24px;
      border-radius: var(--radius-md);
      font-size: .9375rem;
      font-weight: 600;
      transition: all .2s ease;
      white-space: nowrap;
    }
    .btn-primary {
      background: var(--accent);
      color: var(--white);
    }
    .btn-primary:hover { background: var(--accent-hover); transform: translateY(-1px); box-shadow: 0 4px 16px rgba(91,75,255,.35); }
    .btn-primary:active { transform: translateY(0); }
    .btn-ghost {
      background: transparent;
      color: var(--black);
      border: 1.5px solid var(--gray-200);
    }
    .btn-ghost:hover { border-color: var(--gray-400); background: var(--gray-50); }
    .btn-lg { padding: 14px 28px; font-size: 1rem; }

    /* ── Announcement Bar ── */
    .announcement-bar {
      background: var(--black);
      color: var(--white);
      text-align: center;
      padding: 10px 24px;
      font-size: .8125rem;
      font-weight: 500;
      letter-spacing: .01em;
    }
    .announcement-bar a { color: var(--white); text-decoration: underline; text-underline-offset: 3px; opacity: .85; }
    .announcement-bar a:hover { opacity: 1; }

    /* ── Navigation ── */
    .navbar {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--gray-200);
    }
    .navbar-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
    }
    .navbar-logo {
      font-size: 1.1rem;
      font-weight: 700;
      letter-spacing: -.02em;
      color: var(--black);
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .navbar-logo-icon {
      width: 28px; height: 28px;
      background: var(--accent);
      border-radius: 7px;
      display: flex; align-items: center; justify-content: center;
    }
    .navbar-logo-icon svg { width: 16px; height: 16px; }
    .navbar-links {
      display: flex;
      align-items: center;
      gap: 32px;
      list-style: none;
    }
    .navbar-links a {
      font-size: .9rem;
      font-weight: 500;
      color: var(--gray-600);
      transition: color .15s;
    }
    .navbar-links a:hover { color: var(--black); }
    .navbar-cta {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .navbar-cta .btn { padding: 9px 18px; font-size: .875rem; }

    @media (max-width: 768px) {
      .navbar-links { display: none; }
    }

    /* ── Hero ── */
    .hero {
      padding: 80px 0 72px;
      text-align: center;
      background: linear-gradient(180deg, #fafafa 0%, var(--white) 100%);
    }
    .hero-eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: var(--accent-light);
      color: var(--accent);
      border-radius: 999px;
      padding: 5px 14px;
      font-size: .8rem;
      font-weight: 600;
      letter-spacing: .02em;
      text-transform: uppercase;
      margin-bottom: 24px;
    }
    .hero-title {
      font-size: clamp(2.2rem, 5vw, 4rem);
      font-weight: 700;
      letter-spacing: -.03em;
      line-height: 1.1;
      max-width: 720px;
      margin: 0 auto 20px;
    }
    .hero-title span { color: var(--accent); }
    .hero-subtitle {
      font-size: clamp(1rem, 2vw, 1.2rem);
      color: var(--gray-600);
      max-width: 520px;
      margin: 0 auto 36px;
      line-height: 1.6;
    }
    .hero-ctas {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 12px;
      flex-wrap: wrap;
      margin-bottom: 56px;
    }
    .hero-note {
      font-size: .8rem;
      color: var(--gray-400);
      margin-top: 12px;
    }
    .hero-screenshots {
      position: relative;
      overflow: hidden;
      border-radius: var(--radius-xl);
      border: 1px solid var(--gray-200);
      box-shadow: var(--shadow-lg);
      max-width: 960px;
      margin: 0 auto;
      background: var(--gray-100);
      min-height: 360px;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 2px;
    }
    .hero-screenshot-card {
      background: var(--gray-200);
      aspect-ratio: 9/16;
      border-radius: 4px;
      overflow: hidden;
      position: relative;
    }
    .hero-screenshot-card .mock-screen {
      width: 100%; height: 100%;
      background: linear-gradient(145deg, #e8e8ff 0%, #f0edff 50%, #e4e0ff 100%);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 12px;
    }
    .mock-bar {
      width: 70%; height: 8px;
      background: rgba(91,75,255,.2);
      border-radius: 4px;
    }
    .mock-bar.short { width: 50%; }
    .mock-bar.xs { width: 35%; height: 6px; }
    .mock-img-placeholder {
      width: 80%; aspect-ratio: 16/9;
      background: rgba(91,75,255,.12);
      border-radius: 6px;
    }
    .hero-screenshot-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(0deg, rgba(255,255,255,.6) 0%, transparent 40%);
      pointer-events: none;
    }

    /* ── Trusted By ── */
    .trusted-by {
      padding: 48px 0;
      border-top: 1px solid var(--gray-200);
      border-bottom: 1px solid var(--gray-200);
      background: var(--white);
    }
    .trusted-by-label {
      text-align: center;
      font-size: .8125rem;
      font-weight: 600;
      color: var(--gray-400);
      letter-spacing: .08em;
      text-transform: uppercase;
      margin-bottom: 28px;
    }
    .brands-row {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 40px;
      flex-wrap: wrap;
    }
    .brand-logo {
      font-size: .9rem;
      font-weight: 700;
      color: var(--gray-400);
      letter-spacing: -.01em;
      transition: color .2s;
      user-select: none;
    }
    .brand-logo:hover { color: var(--gray-600); }

    /* ── Stats ── */
    .stats {
      background: var(--gray-50);
      border-top: 1px solid var(--gray-200);
      border-bottom: 1px solid var(--gray-200);
    }
    .stats-inner {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 2px;
    }
    .stat-card {
      padding: 56px 40px;
      text-align: center;
      background: var(--white);
    }
    .stat-card:first-child { border-radius: var(--radius-lg) 0 0 var(--radius-lg); }
    .stat-card:last-child  { border-radius: 0 var(--radius-lg) var(--radius-lg) 0; }
    .stat-number {
      font-size: clamp(2.5rem, 5vw, 4rem);
      font-weight: 700;
      letter-spacing: -.04em;
      color: var(--black);
      line-height: 1;
      margin-bottom: 10px;
    }
    .stat-number span { color: var(--accent); }
    .stat-label {
      font-size: 1rem;
      color: var(--gray-600);
      font-weight: 500;
    }
    .stats-caption {
      text-align: center;
      font-size: .875rem;
      color: var(--gray-400);
      margin-top: 32px;
    }

    @media (max-width: 640px) {
      .stats-inner { grid-template-columns: 1fr; gap: 1px; }
      .stat-card:first-child { border-radius: var(--radius-lg) var(--radius-lg) 0 0; }
      .stat-card:last-child  { border-radius: 0 0 var(--radius-lg) var(--radius-lg); }
    }

    /* ── Section Header ── */
    .section-header {
      text-align: center;
      margin-bottom: 56px;
    }
    .section-tag {
      display: inline-block;
      background: var(--accent-light);
      color: var(--accent);
      border-radius: 999px;
      padding: 4px 14px;
      font-size: .78rem;
      font-weight: 700;
      letter-spacing: .06em;
      text-transform: uppercase;
      margin-bottom: 16px;
    }
    .section-title {
      font-size: clamp(1.75rem, 3.5vw, 2.625rem);
      font-weight: 700;
      letter-spacing: -.03em;
      line-height: 1.15;
      margin-bottom: 14px;
    }
    .section-subtitle {
      font-size: 1.0625rem;
      color: var(--gray-600);
      max-width: 520px;
      margin: 0 auto;
      line-height: 1.6;
    }

    /* ── Feature: Search ── */
    .features-search-box {
      background: var(--gray-50);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-xl);
      overflow: hidden;
    }
    .search-tabs {
      display: flex;
      align-items: center;
      gap: 0;
      padding: 0 24px;
      border-bottom: 1px solid var(--gray-200);
      background: var(--white);
      overflow-x: auto;
      scrollbar-width: none;
    }
    .search-tabs::-webkit-scrollbar { display: none; }
    .search-tab {
      padding: 16px 20px;
      font-size: .9rem;
      font-weight: 500;
      color: var(--gray-600);
      border: none;
      background: none;
      border-bottom: 2px solid transparent;
      margin-bottom: -1px;
      cursor: pointer;
      white-space: nowrap;
      transition: color .2s, border-color .2s;
    }
    .search-tab.active {
      color: var(--accent);
      border-bottom-color: var(--accent);
      font-weight: 600;
    }
    .search-tab:hover:not(.active) { color: var(--black); }

    .filter-pills-row {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 16px 24px;
      overflow-x: auto;
      scrollbar-width: none;
      border-bottom: 1px solid var(--gray-200);
      background: var(--white);
    }
    .filter-pills-row::-webkit-scrollbar { display: none; }
    .filter-pill {
      padding: 6px 16px;
      border-radius: 999px;
      border: 1.5px solid var(--gray-200);
      background: var(--white);
      font-size: .8125rem;
      font-weight: 500;
      color: var(--gray-600);
      cursor: pointer;
      white-space: nowrap;
      transition: all .2s ease;
    }
    .filter-pill.active {
      background: var(--accent);
      color: var(--white);
      border-color: var(--accent);
    }
    .filter-pill:hover:not(.active) {
      border-color: var(--accent);
      color: var(--accent);
    }

    .screenshot-grid {
      padding: 24px;
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
      gap: 12px;
      min-height: 320px;
    }
    .screenshot-card {
      border-radius: var(--radius-md);
      overflow: hidden;
      border: 1px solid var(--gray-200);
      background: var(--white);
      transition: all .25s ease;
      cursor: pointer;
      display: none;
    }
    .screenshot-card.visible {
      display: block;
    }
    .screenshot-card:hover {
      transform: translateY(-3px);
      box-shadow: var(--shadow-md);
      border-color: var(--accent);
    }
    .screenshot-card-img {
      aspect-ratio: 9/16;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 6px;
      padding: 10px;
    }
    .screenshot-card-label {
      padding: 8px 10px;
      font-size: .7rem;
      font-weight: 600;
      color: var(--gray-600);
      border-top: 1px solid var(--gray-200);
      background: var(--gray-50);
    }

    /* Color themes per category */
    .cat-profile   { background: linear-gradient(135deg, #dbeafe, #eff6ff); }
    .cat-wallet    { background: linear-gradient(135deg, #d1fae5, #ecfdf5); }
    .cat-welcome   { background: linear-gradient(135deg, #ede9fe, #f5f3ff); }
    .cat-setup     { background: linear-gradient(135deg, #fef9c3, #fffde8); }
    .cat-home      { background: linear-gradient(135deg, #fee2e2, #fff5f5); }
    .cat-sub       { background: linear-gradient(135deg, #fce7f3, #fff0f8); }
    .cat-login     { background: linear-gradient(135deg, #e0f2fe, #f0faff); }
    .cat-settings  { background: linear-gradient(135deg, #f1f5f9, #f8fafc); }
    .cat-checkout  { background: linear-gradient(135deg, #fef3c7, #fffbeb); }
    .cat-collection{ background: linear-gradient(135deg, #e8f5e9, #f1f8e9); }

    /* Tab content panels */
    .tab-panel { display: none; }
    .tab-panel.active { display: block; }

    /* Elements grid */
    .elements-grid {
      padding: 24px;
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
      gap: 12px;
      min-height: 320px;
    }
    .element-card {
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-md);
      background: var(--white);
      padding: 20px;
      transition: all .25s ease;
      cursor: pointer;
    }
    .element-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); border-color: var(--accent); }
    .element-tag {
      display: inline-block;
      background: var(--accent-light);
      color: var(--accent);
      border-radius: 4px;
      padding: 3px 8px;
      font-size: .7rem;
      font-weight: 600;
      margin-bottom: 10px;
    }
    .element-name { font-size: .85rem; font-weight: 600; margin-bottom: 4px; }
    .element-count { font-size: .75rem; color: var(--gray-400); }

    .flows-preview {
      padding: 24px;
      min-height: 320px;
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
      gap: 12px;
    }
    .flow-card {
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-md);
      background: var(--white);
      overflow: hidden;
      transition: all .25s ease;
      cursor: pointer;
    }
    .flow-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); border-color: var(--accent); }
    .flow-card-screens {
      display: flex;
      gap: 2px;
      padding: 12px;
      background: var(--gray-50);
    }
    .flow-screen-mini {
      flex: 1;
      aspect-ratio: 9/16;
      border-radius: 4px;
      max-width: 42px;
    }
    .flow-card-info { padding: 12px; }
    .flow-card-name { font-size: .8rem; font-weight: 600; margin-bottom: 2px; }
    .flow-card-count { font-size: .72rem; color: var(--gray-400); }

    .text-search-panel {
      padding: 24px;
      min-height: 320px;
    }
    .text-search-bar {
      display: flex;
      align-items: center;
      gap: 12px;
      background: var(--white);
      border: 1.5px solid var(--gray-200);
      border-radius: var(--radius-md);
      padding: 12px 16px;
      margin-bottom: 20px;
    }
    .text-search-bar input {
      flex: 1; border: none; outline: none;
      font-family: inherit; font-size: .9rem;
      color: var(--black);
    }
    .text-search-bar input::placeholder { color: var(--gray-400); }
    .text-result-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
      gap: 10px;
    }
    .text-result-card {
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-md);
      background: var(--white);
      padding: 12px;
      transition: all .25s ease;
      cursor: pointer;
    }
    .text-result-card:hover { border-color: var(--accent); }
    .text-highlight {
      display: inline-block;
      background: #fef08a;
      border-radius: 2px;
      font-size: .72rem;
      font-weight: 600;
      padding: 1px 4px;
      margin-bottom: 6px;
    }
    .text-result-app { font-size: .72rem; color: var(--gray-400); margin-top: 4px; }

    /* ── Feature: Flows ── */
    .flows-section { background: var(--gray-50); }
    .flows-toggle-wrap {
      display: flex;
      justify-content: center;
      margin-bottom: 40px;
    }
    .flows-toggle {
      display: flex;
      background: var(--gray-200);
      border-radius: 999px;
      padding: 4px;
      gap: 4px;
    }
    .flows-toggle-btn {
      padding: 9px 24px;
      border-radius: 999px;
      font-size: .875rem;
      font-weight: 600;
      color: var(--gray-600);
      background: transparent;
      border: none;
      cursor: pointer;
      transition: all .25s ease;
    }
    .flows-toggle-btn.active {
      background: var(--white);
      color: var(--black);
      box-shadow: 0 1px 6px rgba(0,0,0,.1);
    }
    .flows-content-area {
      max-width: 900px;
      margin: 0 auto;
      border-radius: var(--radius-xl);
      overflow: hidden;
      border: 1px solid var(--gray-200);
      box-shadow: var(--shadow-lg);
    }
    .flows-panel { display: none; }
    .flows-panel.active { display: block; }
    .flows-video-mock {
      background: var(--black);
      aspect-ratio: 16/9;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
    }
    .play-button {
      width: 72px; height: 72px;
      background: rgba(255,255,255,.15);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      backdrop-filter: blur(6px);
      border: 1.5px solid rgba(255,255,255,.25);
      cursor: pointer;
      transition: transform .2s, background .2s;
    }
    .play-button:hover { transform: scale(1.08); background: rgba(255,255,255,.22); }
    .play-button svg { margin-left: 4px; }
    .video-screen-preview {
      display: flex;
      gap: 12px;
      padding: 20px;
      background: var(--white);
      overflow-x: auto;
    }
    .video-screen-thumb {
      min-width: 72px;
      aspect-ratio: 9/16;
      border-radius: 8px;
      border: 2px solid transparent;
      cursor: pointer;
      transition: border-color .2s;
    }
    .video-screen-thumb.selected { border-color: var(--accent); }

    .prototype-mock {
      background: var(--white);
      padding: 32px;
      display: grid;
      grid-template-columns: 1fr 2fr;
      gap: 32px;
      align-items: start;
    }
    .prototype-screen-frame {
      border-radius: 20px;
      border: 1.5px solid var(--gray-200);
      overflow: hidden;
      aspect-ratio: 9/19;
      background: linear-gradient(145deg, #ede9fe, #f5f3ff);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 16px;
    }
    .proto-bar { width: 70%; height: 10px; background: rgba(91,75,255,.25); border-radius: 5px; }
    .proto-bar.short { width: 50%; height: 8px; }
    .proto-bar.xs { width: 30%; height: 6px; }
    .proto-btn-mock {
      width: 80%;
      height: 36px;
      background: var(--accent);
      border-radius: 8px;
      margin-top: 8px;
      opacity: .8;
    }
    .prototype-steps {
      display: flex;
      flex-direction: column;
      gap: 12px;
    }
    .proto-step {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      padding: 14px 16px;
      border-radius: var(--radius-md);
      border: 1.5px solid var(--gray-200);
      cursor: pointer;
      transition: all .2s;
    }
    .proto-step.active { border-color: var(--accent); background: var(--accent-light); }
    .proto-step-num {
      width: 24px; height: 24px;
      border-radius: 50%;
      background: var(--gray-200);
      font-size: .7rem;
      font-weight: 700;
      display: flex; align-items: center; justify-content: center;
      flex-shrink: 0;
      color: var(--gray-600);
    }
    .proto-step.active .proto-step-num { background: var(--accent); color: var(--white); }
    .proto-step-name { font-size: .85rem; font-weight: 600; }
    .proto-step-desc { font-size: .75rem; color: var(--gray-600); }

    @media (max-width: 640px) {
      .prototype-mock { grid-template-columns: 1fr; }
    }

    /* ── Features Tools ── */
    .tools-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }
    .tool-card {
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-xl);
      overflow: hidden;
      transition: all .25s ease;
    }
    .tool-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); border-color: var(--gray-300); }
    .tool-card-preview {
      background: var(--gray-50);
      padding: 28px 24px 16px;
      min-height: 180px;
      display: flex;
      align-items: flex-end;
      justify-content: center;
      border-bottom: 1px solid var(--gray-200);
    }
    .tool-card-preview-inner {
      width: 100%;
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-md);
      padding: 12px;
      box-shadow: var(--shadow-sm);
    }
    .tool-mock-row {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 6px 0;
    }
    .tool-mock-icon {
      width: 28px; height: 28px;
      background: var(--accent-light);
      border-radius: 6px;
      flex-shrink: 0;
    }
    .tool-mock-bar { flex: 1; height: 8px; background: var(--gray-200); border-radius: 4px; }
    .tool-mock-bar.sm { width: 60%; }
    .tool-card-body { padding: 24px; }
    .tool-card-title { font-size: 1.05rem; font-weight: 700; margin-bottom: 6px; }
    .tool-card-desc { font-size: .875rem; color: var(--gray-600); line-height: 1.6; }
    .tool-card-badge {
      display: inline-flex;
      align-items: center;
      gap: 5px;
      background: var(--accent-light);
      color: var(--accent);
      border-radius: 999px;
      padding: 3px 10px;
      font-size: .72rem;
      font-weight: 700;
      margin-top: 12px;
    }

    @media (max-width: 900px) { .tools-grid { grid-template-columns: 1fr; } }
    @media (min-width: 641px) and (max-width: 900px) { .tools-grid { grid-template-columns: repeat(2, 1fr); } }

    /* ── Testimonials ── */
    .testimonials { background: var(--gray-50); border-top: 1px solid var(--gray-200); }
    .marquee-wrapper {
      overflow: hidden;
      position: relative;
    }
    .marquee-wrapper::before,
    .marquee-wrapper::after {
      content: '';
      position: absolute;
      top: 0; bottom: 0;
      width: 80px;
      z-index: 2;
      pointer-events: none;
    }
    .marquee-wrapper::before { left: 0; background: linear-gradient(90deg, var(--gray-50), transparent); }
    .marquee-wrapper::after  { right: 0; background: linear-gradient(-90deg, var(--gray-50), transparent); }

    .marquee-row {
      display: flex;
      gap: 16px;
      margin-bottom: 16px;
    }
    .marquee-track {
      display: flex;
      gap: 16px;
      animation: marquee 40s linear infinite;
      will-change: transform;
    }
    .marquee-track-reverse {
      animation: marquee-reverse 40s linear infinite;
    }
    @keyframes marquee {
      0%   { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }
    @keyframes marquee-reverse {
      0%   { transform: translateX(-50%); }
      100% { transform: translateX(0); }
    }
    .marquee-row:hover .marquee-track { animation-play-state: paused; }
    .testimonial-card {
      flex-shrink: 0;
      width: 340px;
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      padding: 24px;
      box-shadow: var(--shadow-sm);
    }
    .testimonial-stars {
      display: flex;
      gap: 3px;
      margin-bottom: 14px;
    }
    .star { color: #f59e0b; font-size: .875rem; }
    .testimonial-quote {
      font-size: .9rem;
      line-height: 1.65;
      color: var(--black);
      margin-bottom: 18px;
    }
    .testimonial-author { display: flex; align-items: center; gap: 12px; }
    .author-avatar {
      width: 36px; height: 36px;
      border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
      font-size: .8rem;
      font-weight: 700;
      color: var(--white);
      flex-shrink: 0;
    }
    .author-name { font-size: .875rem; font-weight: 700; }
    .author-role { font-size: .75rem; color: var(--gray-400); }

    /* ── CTA Section ── */
    .cta-section {
      padding: 96px 0 64px;
      text-align: center;
      overflow: hidden;
      background: var(--white);
    }
    .cta-inner {
      max-width: 600px;
      margin: 0 auto 56px;
    }
    .cta-title {
      font-size: clamp(2rem, 4vw, 3rem);
      font-weight: 700;
      letter-spacing: -.03em;
      margin-bottom: 16px;
      line-height: 1.15;
    }
    .cta-subtitle {
      font-size: 1.0625rem;
      color: var(--gray-600);
      margin-bottom: 32px;
      line-height: 1.6;
    }
    .cta-buttons {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 12px;
      flex-wrap: wrap;
    }
    .app-icons-section { overflow: hidden; position: relative; }
    .app-icons-section::before,
    .app-icons-section::after {
      content: '';
      position: absolute;
      top: 0; bottom: 0;
      width: 120px;
      z-index: 2;
      pointer-events: none;
    }
    .app-icons-section::before { left: 0; background: linear-gradient(90deg, var(--white), transparent); }
    .app-icons-section::after  { right: 0; background: linear-gradient(-90deg, var(--white), transparent); }
    .app-icon-row {
      display: flex;
      gap: 12px;
      margin-bottom: 12px;
    }
    .app-icon-track {
      display: flex;
      gap: 12px;
      animation: marquee 25s linear infinite;
    }
    .app-icon-track-r {
      animation: marquee-reverse 28s linear infinite;
    }
    .app-icon-chip {
      flex-shrink: 0;
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 8px 16px;
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: 999px;
      box-shadow: var(--shadow-sm);
      white-space: nowrap;
    }
    .app-icon-dot {
      width: 20px; height: 20px;
      border-radius: 5px;
      flex-shrink: 0;
    }
    .app-icon-name {
      font-size: .8rem;
      font-weight: 600;
      color: var(--black);
    }

    /* ── Footer ── */
    .footer {
      background: var(--black);
      color: var(--white);
      padding: 56px 0 32px;
    }
    .footer-top {
      display: grid;
      grid-template-columns: 2fr 1fr 1fr 1fr;
      gap: 48px;
      margin-bottom: 48px;
    }
    .footer-brand-name {
      font-size: 1.05rem;
      font-weight: 700;
      margin-bottom: 10px;
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .footer-brand-icon {
      width: 26px; height: 26px;
      background: var(--accent);
      border-radius: 6px;
      display: flex; align-items: center; justify-content: center;
    }
    .footer-tagline {
      font-size: .875rem;
      color: rgba(255,255,255,.5);
      line-height: 1.6;
      max-width: 260px;
    }
    .footer-col-title {
      font-size: .75rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: .08em;
      color: rgba(255,255,255,.4);
      margin-bottom: 16px;
    }
    .footer-links { list-style: none; display: flex; flex-direction: column; gap: 10px; }
    .footer-links a {
      font-size: .875rem;
      color: rgba(255,255,255,.65);
      transition: color .15s;
    }
    .footer-links a:hover { color: var(--white); }
    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,.1);
      padding-top: 28px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 12px;
    }
    .footer-copy {
      font-size: .8125rem;
      color: rgba(255,255,255,.4);
    }
    .footer-legal { display: flex; gap: 20px; }
    .footer-legal a {
      font-size: .8125rem;
      color: rgba(255,255,255,.4);
      transition: color .15s;
    }
    .footer-legal a:hover { color: rgba(255,255,255,.7); }

    @media (max-width: 900px) {
      .footer-top { grid-template-columns: 1fr 1fr; }
    }
    @media (max-width: 560px) {
      .footer-top { grid-template-columns: 1fr; }
    }

    /* ── Utilities ── */
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

    /* Loading state for counter */
    .counter-value { transition: none; }

    @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');
  </style>
</head>
